\label{thm:ami}
Adopt the notation from  \cref{sec:defining}. Suppose that a conditionally novel model of the whole does not tie the separate two-part descriptions of the parts; that is:
\begin{align}
    \label{eq:no_neutral_ties}
    C(x_a,x_b\to x)>0
    \quad\implies\quad
    K(m_x)+l_{m_x}(x)
    \neq
    K(m_{x_a})+l_{m_{x_a}}(x_a)
    +
    K(m_{x_b})+l_{m_{x_b}}(x_b) .
\end{align}
Then:
\begin{align}
    C(x_a,x_b\to x)>0
    \implies
    I(x_a:x_b)>0 ,
\end{align}
but reverse implication does not hold in general.

\label{cor:maximal_compositionality_bound}
Suppose that the Occam's razor models of both one-bit
strings coincide with a fixed empty model:
\begin{align}
    m_0 = m_1 = m_{\varnothing}.
\end{align}
For every nonempty binary string $x$ of length $n$,
any maximizing decomposition $T_x^{\mathrm{max}}$ satisfies
\begin{align}
    S_{T_x^{\mathrm{max}}}(x)
    \geq K(m_x) - K(n) - O(1).
\end{align}
Consequently, suppressing an additive
$O(\log(n+2))$ term gives
$S_{T_x^{\mathrm{max}}}(x)\geq K(m_x)$.

\label{cor:minimal_complete}
Let $x\in\{0,1\}^n$, with $n\geq 2$, and suppose
$m_0=m_1=m_{\varnothing}$ for a fixed empty model.
Let $\mathcal{T}_{\mathrm{complete}}(x)$ consist of all
rooted, ordered decomposition trees with single-bit
leaves and at least two children per internal node.

The single-join tree $T_\star$, whose root has all $n$
bits as its immediate children, satisfies
\begin{align}
    S_{T_\star}(x)=K(m_x\mid n)+O(1).
\end{align}
Moreover,
\begin{align}
    K(m_x)-O(n)
    \leq \min_{T\in\mathcal{T}_{\mathrm{complete}}(x)}
             S_T(x)
    \leq K(m_x\mid n)+O(1).
\end{align}
Under the convention of suppressing leaf-description
and accumulated coding terms, these bounds give
\begin{align}
    \min_{T\in\mathcal{T}_{\mathrm{complete}}(x)}
        S_T(x)=K(m_x),
\end{align}
with the single-join tree providing a trivial minimizer
in this idealized accounting.

\label{cor:minimal_unrestricted}
If decomposition trees may terminate at arbitrary
nonempty substrings, then for every nonempty string $x$,
\begin{align}
    \min_T S_T(x)=0.
\end{align}
A minimizer is the tree consisting only of the root,
labelled by $x$.

\label{thm:recursive_consistency}
Fix the universal machine, the tuple encoding, and a uniquely selected Occam's razor model $m_y$ for every nonempty substring $y$ of $x$. Let $\mathcal{T}(y)$ be the set of finite rooted, ordered decomposition trees of $y$ whose nodes represent nonempty substrings and whose internal nodes have at least two children. Define
\begin{align}
    S^{\mathrm{max}}(y)
    := \max_{R\in\mathcal{T}(y)} S_R(y).
\end{align}
If $T\in\mathcal{T}(x)$ maximizes $S_T(x)$, then, for every node $v$ of $T$, the subtree $T_v$ rooted at $v$ satisfies
\begin{align}
    S_{T_v}(x_v) = S^{\mathrm{max}}(x_v).
\end{align}
Moreover, replacing $T_v$ by any maximizing decomposition of $x_v$ produces another maximizing decomposition of $x$.

\label{thm:binary_refinement}
Fix the universal prefix machine, the tuple encoding, and a uniquely selected Occam's razor model $m_y$ for every nonempty substring $y$ of a nonempty string $x$. Let $\mathcal{T}(x)$ consist of the finite rooted, ordered decomposition trees of $x$ whose nodes represent nonempty substrings and whose internal nodes have at least two children. Write
\begin{align}
    S_T(x) &:= \sum_{v\in\mathrm{Int}(T)} K(m_{x_v}\mid m_{x_{v_1}},\ldots,m_{x_{v_{k_v}}}), \\
    N_{>2}(T) &:= \bigl|\{v\in\mathrm{Int}(T):k_v>2\}\bigr|.
\end{align}
There is a constant $c\geq 0$, independent of $x$ and $T$, such that every $T\in\mathcal{T}(x)$ admits a binary refinement $B$ with the same ordered leaves and
\begin{align}
    S_B(x) \geq S_T(x)-cN_{>2}(T).
    \label{eq:binary_refinement_bound}
\end{align}
Consequently, under the convention of suppressing these accumulated additive coding terms, a maximizing decomposition can be chosen to consist entirely of binary joins.

First consider a single join $y=[y_1,\ldots,y_k]$, where $k\geq 3$, and set $z_j=[y_1,\ldots,y_j]$ for $1\leq j\leq k$. Its left-associated binary refinement joins $z_{j-1}$ with $y_j$ to form $z_j$, successively for $j=2,\ldots,k$. We claim that
\begin{align}
    K(m_y\mid m_{y_1},\ldots,m_{y_k})
    \leq \sum_{j=2}^{k} K(m_{z_j}\mid m_{z_{j-1}},m_{y_j})+c.
    \label{eq:binary_join_bound}
\end{align}
For each $j$, choose a shortest prefix program $p_j$ that outputs $m_{z_j}$ given $(m_{z_{j-1}},m_{y_j})$. Given the tuple $(m_{y_1},\ldots,m_{y_k})$, a fixed decoder reads the concatenated programs $p_2\cdots p_k$. It starts with $m_{z_1}=m_{y_1}$ and recursively runs $p_j$ with the previously recovered model $m_{z_{j-1}}$ and the supplied model $m_{y_j}$. The final output is $m_{z_k}=m_y$. The input tuple determines $k$, and prefix-freeness permits the programs to be parsed successively without additional delimiters. Thus their total length, plus a fixed simulation constant $c$, bounds the conditional complexity of $m_y$, proving equation~\ref{eq:binary_join_bound}. In particular, $c$ does not depend on $k$. This construction does not require computing an Occam's razor model from its substring: each intermediate model is supplied by its corresponding program.

Now recursively refine the original tree. At each node with more than two children, replace its join by the left-associated binary chain just described, preserving the original child subtrees. The node still represents the same substring, so its parent's score is unchanged; scores within the original child subtrees are also unchanged. Equation~\ref{eq:binary_join_bound} shows that the replacement decreases the total score by at most $c$. Nodes already having two children need no replacement. After replacing all $N_{>2}(T)$ nonbinary joins, the resulting tree $B$ is binary and has the same ordered leaves. Summing the local bounds proves equation~\ref{eq:binary_refinement_bound}.

There are finitely many admissible trees, so a maximizer exists. In the idealized accounting that suppresses the indicated coding terms, refining a maximizer cannot decrease its score, and maximality prevents an increase beyond the maximum. Its binary refinement is therefore also a maximizer in that accounting.
